import{_ as a,o as n,c as i,ag as e}from"./chunks/framework.PVHj0As1.js";const t="/pub-blog/assets/image-20250228080622721.BTduavg-.png",l="/pub-blog/assets/image-20250228081107664.Df26q38J.png",p="/pub-blog/assets/image-20250228081131673.CQGyoBsh.png",r="/pub-blog/assets/5aaf9a8cd07849f992177eab17163f97.xQ1A6_ld.png",h="/pub-blog/assets/174728b890ea4f90be5e161686237b87.B6yfB4Q3.png",o="/pub-blog/assets/c6bb117726d740ccba115c49779332a3.BIcwnGpb.png",c="/pub-blog/assets/e5590494264a4c77931cbf679b36ba3f.04MHneAD.png",g="/pub-blog/assets/image-20250228081423113.Byt_Y8Sm.png",d="/pub-blog/assets/image-20250228081759934.CdQx4rH5.png",k="/pub-blog/assets/image-20250228081859783.BBqBEg7y.png",u="/pub-blog/assets/image-20250228082008770.BUPDz98d.png",b="/pub-blog/assets/image-20250228082526462.DSzpQoiB.png",m="data:image/png;base64,",E="/pub-blog/assets/image-20250228082720401.BdJ3cTIW.png",I="/pub-blog/assets/image-20250228082817873.CIU-KigQ.png",y="/pub-blog/assets/image-20250228082958252.jjD_k2Q8.png",f="/pub-blog/assets/image-20250228083113923.7jjswSCL.png",A="/pub-blog/assets/image-20250228083157763.BL9WaZ6k.png",x=JSON.parse('{"title":"Trae 最强 claude 3.7 带你体验面相算命","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/Trae 最强 claude 3.7 带你体验科学算命/Trae 最强 claude 3.7 带你体验科学算命.md","filePath":"AI人工智能/Trae 最强 claude 3.7 带你体验科学算命/Trae 最强 claude 3.7 带你体验科学算命.md","lastUpdated":1740703457000,"__rawMarkdown":"# Trae 最强 claude 3.7 带你体验面相算命\\n\\n\\n\\n## claude 3.7 介绍\\n\\n新一代Trae在2025年2月27日最新版本直接内置了[claude 3.7](https://claude.ai)，这一重大更新可谓是将 Trae 的AI协助能力提到了巅峰。\\n\\n> 1. **混合推理模式的创新性**\\n>    Claude 3.7的核心创新在于“一个模型，两种思考方式”——标准模式（快速响应）和扩展模式（分步推理）。这种设计允许用户根据需求灵活切换，既能处理简单问题，又能应对复杂逻辑推理任务，例如数学推导或代码调试。相比之下，开源模型如DeepSeek-R1通常仅针对单一推理场景优化，缺乏动态模式切换能力。\\n> 2. **透明化推理与安全性**\\n>    扩展模式下，Claude 3.7会展示完整的思维链（Chain-of-Thought），用户可实时监控其推理过程，这在提高信任度的同时，也有助于开发者优化模型行为。而开源模型虽然允许代码级调整，但需用户自行设计监控机制，门槛较高。\\n\\n![image-20250228080622721](assets/image-20250228080622721.png)\\n\\n## Trae 介绍\\n\\n![image-20250228081107664](assets/image-20250228081107664.png)\\n\\nTrae（/treɪ/）与 AI 深度集成，提供智能问答、代码自动补全以及基于 Agent 的 AI 自动编程能力。使用 Trae 开发项目时，你可以与 AI 灵活协作，提升开发效率。\\n\\n> [使用教程](https://docs.trae.ai/docs/what-is-trae?_lang=zh)\\n\\n## Trae 安装\\n\\n本文档介绍如何安装 Trae 并完成基础配置。\\n\\n### 下载和安装\\n\\n在[官网](https://www.trae.ai/)上下载对应你系统的Trae\\n\\n![image-20250228081131673](assets/image-20250228081131673.png)\\n\\n按照成功后，启动它\\n\\n![img](assets/5aaf9a8cd07849f992177eab17163f97.png)\\n\\n### 选择主题和语言\\n\\n![img](assets/174728b890ea4f90be5e161686237b87.png)\\n\\n### 导入配置\\n\\nTrae可以从你的vscode 或者 cursor中导入插件和配置\\n\\n![img](assets/c6bb117726d740ccba115c49779332a3.png)\\n\\n### 添加 Trae 相关的命令行\\n\\n添加 Trae 相关的命令行后，你可以在终端中使用命令行更快速地完成 Trae 相关的操作。例如：\\n\\n- 使用 trae 命令快速唤起 Trae。\\n- 使用 trae my-react-app 命令在 Trae 中打开一个项目。\\n\\n点击 **安装 `trae` 命令** 按钮，然后完成授权流程。\\n\\n![img](assets/e5590494264a4c77931cbf679b36ba3f.png)\\n\\n### 登录\\n\\nTrae 提供了三种登录方式，分别为 Google 账号登录、Github 账号登录、邮箱登录。这里需要特别注意的是，实现登录功能，目前需要魔法上网。\\n\\n![image-20250228081423113](assets/image-20250228081423113.png)\\n\\n\\n\\n## 面相算命\\n\\n\\n\\n### 面相算命 项目背景\\n\\n一直以来都感觉科学和传统相结合的产品很微妙，在目前AI工具大行其道的形势下，有不同背景、不同角色的人在使用AI工具帮助我们在生活中和工作中提效，面相算命也是很多人需要的一种功能，这里主要通过Trae+Claude+vue+github，无须一行代码，带你实现在线的面相算命应用。\\n\\n### 面相算命 介绍\\n\\n面相算命是一个基于人工智能的面部分析应用，通过分析用户面部特征，生成有趣的性格、事业和婚姻运势分析结果。该项目仅供娱乐，将人脸识别技术与传统面相学相结合，创造了一种新颖的交互体验。\\n\\n### 功能特点\\n\\n- **实时人脸检测**：使用摄像头实时捕捉用户面部\\n- **面部特征分析**：分析面部轮廓、表情等特征\\n- **性格特点评估**：通过雷达图直观展示性格特点分析\\n- **运势预测**：包含事业、婚姻等方面的运势分析\\n- **每日宜忌**：提供个性化的日常建议\\n- **响应式设计**：适配各种屏幕尺寸的设备\\n\\n### 技术栈\\n\\n- **前端框架**：Vue 3 + Vite\\n- **UI组件库**：Element Plus\\n- **图表可视化**：ECharts\\n- **人脸识别**：face-api.js\\n- **开发语言**：JavaScript\\n\\n### 项目截图\\n\\n![image-20250228081759934](assets/image-20250228081759934.png)\\n\\n---\\n\\n![image-20250228081859783](assets/image-20250228081859783.png)\\n\\n\\n\\n---\\n\\n![image-20250228082008770](assets/image-20250228082008770.png)\\n\\n### 在线体验\\n\\n```\\nhttps://itcastwsy.github.io/-Face-Fortune-\\n```\\n\\n## Trae 实现面相算命\\n\\n### 准备工作\\n\\n1. 新建一个空文件夹，用来存放项目代码\\n2. 然后使用Trae打开它\\n\\n### 开启Build模式\\n\\nBuilder 模式可以帮助你从 0 到 1 开发一个完整的项目。你可以将它无缝融入到项目构建的流程中。\\n\\n使用快捷键（macOS：Command + U；Windows：Ctrl + U）打开侧边对话框。\\n\\n![image-20250228082526462](assets/image-20250228082526462.png)\\n\\n选择Build模式\\n\\n![image-20250228082557187](assets/image-20250228082557187.png)\\n\\n### 开启对话生成代码\\n\\n![image-20250228082720401](assets/image-20250228082720401.png)\\n\\n接下来Trae便会如你所愿开始准备和编码\\n\\n![image-20250228082817873](assets/image-20250228082817873.png)\\n\\n### 生成代码和接收修改\\n\\n在过程中，Trae会不断咨询你是否要接受当前文件的更改，这里都选择了接受。\\n\\n![image-20250228082958252](assets/image-20250228082958252.png)\\n\\n### 完成和预览\\n\\n如果Trae完成工作了，它会提示你进行预览\\n\\n![image-20250228083113923](assets/image-20250228083113923.png)\\n\\n### 修复bug\\n\\n当然，如果程序在实现过程中出现了问题，你可以直接把错误描述，告诉Trae，然后它会进行修复的。\\n\\n![image-20250228083157763](assets/image-20250228083157763.png)\\n\\n\\n\\n\\n\\n\\n\\n## 打包发布上线\\n\\n最后我们可以利用github的page来预览预览这个应用，也利用github的action功能自动实现打包和部署。\\n\\n### 1. 配置 `vite.config.js`\\n\\n确保你的 Vite 项目配置了正确的 `base`（根据仓库名称）：\\n\\n```javascript\\n// vite.config.js\\nexport default defineConfig({\\n  base: process.env.NODE_ENV === \'production\' ? \'/你的仓库名称/\' : \'/\',\\n  // 其他配置...\\n})\\n```\\n\\n### 2. 创建 GitHub Actions 工作流文件\\n\\n在项目根目录创建：`.github/workflows/deploy.yml`\\n\\n```yml\\nname: Deploy to GitHub Pages\\n\\non:\\n  push:\\n    branches: [ \\"main\\" ] # 触发分支（根据你的主分支名称调整）\\n\\njobs:\\n  deploy:\\n    runs-on: ubuntu-latest\\n    permissions:\\n      contents: write # 允许写入权限\\n\\n    steps:\\n    - name: Checkout code\\n      uses: actions/checkout@v4\\n\\n    - name: Setup Node.js\\n      uses: actions/setup-node@v3\\n      with:\\n        node-version: 20\\n\\n    - name: Install dependencies\\n      run: npm install\\n\\n    - name: Build project\\n      run: npm run build\\n\\n    - name: Deploy to GitHub Pages\\n      uses: peaceiris/actions-gh-pages@v3\\n      with:\\n        github_token: ${{ secrets.GITHUB_TOKEN }}\\n        publish_dir: ./dist\\n        # GITHUB_TOKEN 在 setting->secrets and variables->Repository secrets 新建即可\\n        # 如果有自定义域名，添加 cname 配置  \\n        # cname: yourdomain.com\\n```\\n\\n### 3. 启用 GitHub Pages\\n\\n1. 进入仓库的 **Settings** → **Pages**\\n2. 选择部署源：\\n   - **Branch**: `gh-pages`\\n   - **Folder**: `/(root)`\\n3. 点击 **Save**\\n\\n\\n\\n\\n\\n\\n\\n## 仓库地址\\n\\n```\\nhttps://github.com/itcastWsy/-Face-Fortune-\\n```\\n\\n## 在线体验\\n\\n```\\nhttps://itcastwsy.github.io/-Face-Fortune-\\n```\\n\\n## 尾声\\n\\n\\n\\n如果你兴趣想要了解更多的开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。"}'),F={name:"AI人工智能/Trae 最强 claude 3.7 带你体验科学算命/Trae 最强 claude 3.7 带你体验科学算命.md"};function v(T,s,P,D,C,q){return n(),i("div",null,[...s[0]||(s[0]=[e("",84)])])}const R=a(F,[["render",v]]);export{x as __pageData,R as default};
